ruleToc.chapterName:
@css:h6@text
<js>
var TARGET_LANG = 'zh-Hans';
function translateText(text, targetLang){
  if (!text || !text.trim()) return text;
  var AUTH = java.get('AUTH');
  if (!AUTH) {
    AUTH = java.ajax('https://edge.microsoft.com/translate/auth');
    if (typeof AUTH === 'object' && AUTH.toString) AUTH = AUTH.toString();
    java.put('AUTH', AUTH);
  }
  var body = JSON.stringify([text]);
  var headers = {'Authorization': 'Bearer ' + AUTH, 'Content-Type': 'application/json'};
  var option = JSON.stringify({'method': 'post', 'headers': headers, 'body': body});
  var resp = java.ajax('https://edge.microsoft.com/translate/translatetext?to=' + targetLang + ',' + option);
  if (resp && resp.trim()) {
    var arr = JSON.parse(resp);
    if (arr[0] && arr[0].translations && arr[0].translations[0]) {
      return '-' + arr[0].translations[0].text;
    }
  }
  return '-' + text;
}
if (!result) result = '';
if (Array.isArray(result)) {
  result = result.map(function(t){ return translateText(t, TARGET_LANG); });
} else if (typeof result === 'string') {
  result = translateText(result, TARGET_LANG);
}
result;
</js>

ruleToc.chapterUrl:
@css:a@href
<js>
var url = String(result || '');
var nl = url.indexOf('\n');
if (nl >= 0) url = url.substring(0, nl);
url = url.trim();
if (url && !url.startsWith('http')) url = 'https://russtrat.ru' + url;
url;
</js>

ruleToc.nextTocUrl:
@css:.pager-item a@href
<js>
var urls = result;
if (typeof urls === 'string') urls = [urls];
if (!urls) urls = [];
var list = [];
var seen = {};
for (var i = 0; i < urls.length; i++) {
  var u = String(urls[i] || '');
  if (u.indexOf('page=') >= 0) {
    if (u.indexOf('http') < 0) {
      if (u.startsWith('/')) {
        u = 'https://russtrat.ru' + u;
      } else {
        u = 'https://russtrat.ru/analytics?' + u;
      }
    }
    if (!seen[u]) { seen[u] = 1; list.push(u); }
  }
}
list;
</js>

ruleContent.content:
@css:div#printtext > div.field-text@html
<js>
var TARGET_LANG = 'zh-Hans';
var MAX_LEN = 5000;

function getAUTH() {
  var auth = java.get('AUTH_CONTENT');
  if (!auth) {
    auth = java.ajax('https://edge.microsoft.com/translate/auth');
    if (typeof auth === 'object' && auth.toString) auth = auth.toString();
    java.put('AUTH_CONTENT', auth);
  }
  return auth;
}

function translate(text) {
  if (!text || !text.trim() || text.length > MAX_LEN) return text;
  var auth = getAUTH();
  var body = JSON.stringify([text]);
  var headers = {
    'Authorization': 'Bearer ' + auth,
    'Content-Type': 'application/json'
  };
  var option = JSON.stringify({'method': 'post', 'headers': headers, 'body': body});
  var resp = java.ajax('https://edge.microsoft.com/translate/translatetext?to=' + TARGET_LANG + ',' + option);
  if (resp && resp.trim()) {
    try {
      var arr = JSON.parse(resp);
      if (arr[0] && arr[0].translations && arr[0].translations[0]) {
        return arr[0].translations[0].text;
      }
    } catch(e) {}
  }
  return text;
}

// 修复相对路径
result = result.replace(/src="\/sites\//g, 'src="https://russtrat.ru/sites/');
result = result.replace(/href="\/taxonomy\//g, 'href="https://russtrat.ru/taxonomy/');
result = result.replace(/href="\/analytics\//g, 'href="https://russtrat.ru/analytics/');
result = result.replace(/href="\/news\//g, 'href="https://russtrat.ru/news/');

// 用正则提取文本片段并翻译
var BLOCKquote_RE = /<blockquote\b[^>]*>([\s\S]*?)<\/blockquote>/g;
var P_RE = /<p\b[^>]*>([\s\S]*?)<\/p>/g;

function translateTag(tagName, html) {
  var re = new RegExp('<' + tagName + '\\b[^>]*>([\\s\\S]*?)<\\/' + tagName + '>', 'g');
  return html.replace(re, function(match, inner) {
    // 跳过已翻译的中文内容
    var hasChinese = /[\u4e00-\u9fff]/.test(inner);
    if (hasChinese) return match;
    // 提取纯文本并翻译
    var text = inner.replace(/<[^>]+>/g, '').trim();
    if (!text) return match;
    var translated = translate(text);
    if (translated && translated !== text) {
      return '<' + tagName + '>' + translated + '</' + tagName + '>';
    }
    return match;
  });
}

// 翻译 blockquote 和 p
result = translateTag('blockquote', result);
result = translateTag('p', result);

// 翻译其他标签
['h1','h2','h3','h4','h5','h6','li','td','th'].forEach(function(tag) {
  result = translateTag(tag, result);
});

result;
</js>
